/**
 * Trusted composition metadata shared by contained and permission-aware spawners.
 * @since 1.0.0
 */
// The registry key also works when a service crosses the ESM/CJS projections.
// This declares a trusted lifecycle contract; it cannot prove a supplied
// lifecycle is honest or turn process containment into a security sandbox.
const key = Symbol.for("@smthrs/kernel/ContainedSpawner/Lifecycle/v1");
/**
 * Reads only an own data property, without invoking an accessor.
 * @private
 * @since 1.0.0
 */
export const isContained = (spawner) => Object.getOwnPropertyDescriptor(spawner, key)?.value === true;
/**
 * Marks a newly constructed service without copying through object spreads.
 * @private
 * @since 1.0.0
 */
export const mark = (spawner) => Object.defineProperty(spawner, key, { value: true, enumerable: false, writable: false, configurable: false });
/**
 * Preserves the declaration on a wrapper that delegates its process lifetime.
 * @private
 * @since 1.0.0
 */
export const inherit = (source, wrapper) => isContained(source) ? mark(wrapper) : wrapper;

/**
 * Typed capability construction for host decorators.
 *
 * @since 1.0.0-rc.0
 */
import * as Capability from "@smthrs/capability/Capability";
import { GrantStoreError } from "@smthrs/capability/Permission";
import { Effect } from "effect";
/**
 * Constructs decorator requests without leaking schema failures as defects.
 *
 * @category constructors
 * @since 1.0.0-rc.0
 */
export const makeCapability = (action, resource) => Effect.try({
    try: () => Capability.make(action, resource),
    catch: () => new GrantStoreError({
        code: "invalid_resolution",
        message: `capability requires a valid action and a resource within maximumCapabilityResourceLength (${Capability.maxResourceLength} UTF-16 code units)`
    })
});

/**
 * Optional, bounded read batches on the existing filesystem host slot.
 *
 * @since 1.0.0
 */
/** Maximum operations admitted by one batch.
 * @since 1.0.0
 * @category constants
 */
export const maxBatchSize = 128;
/** Bounded concurrency for hosts without batching.
 * @since 1.0.0
 * @category constants
 */
export const fallbackConcurrency = 4;
/** Host extension identity on the guarded filesystem.
 * @since 1.0.0
 * @category constants
 */
export const FileSystemBatchTypeId = Symbol.for("@smthrs/kernel/FileSystemBatch");
/** Discover the guarded batch extension when the host supports it.
 * @since 1.0.0
 * @category accessors
 */
export const batch = (fs) => fs[FileSystemBatchTypeId];

/**
 * Typed host connectivity failures, including failed command diagnostics.
 *
 * @since 1.0.0
 */
import * as Schema from "effect/Schema";
/**
 * A temporarily unreachable resolver, connection, or HTTP service.
 *
 * @category errors
 * @since 1.0.0
 */
export class Unreachable extends Schema.TaggedError()("@smthrs/kernel/Unreachable", {
    message: Schema.String,
    cause: Schema.optional(Schema.Unknown)
}) {
}
const outage = /Could not resolve host|Failed to connect to|Connection timed out|Operation timed out|Connection reset|Recv failure|Network is unreachable|Temporary failure in name resolution|SSL_ERROR_SYSCALL|The remote end hung up unexpectedly|\bEAI_AGAIN\b|\bENOTFOUND\b|\bHTTP(?:\/\d(?:\.\d)?)?\s*(?:(?:error|status|code)\s*[:=]?\s*)?[:=]?\s*(?:429|5\d{2})\b/i;
/**
 * Classifies stderr from a failed host command; other exits keep their domain error.
 *
 * @category constructors
 * @since 1.0.0
 */
export const classifyExit = (stderr) => outage.test(stderr) ? new Unreachable({ message: stderr }) : undefined;
